import { installProps } from "../base/props.js";

const components = new Map();

/** Register a component class under its static `tag`. */
export function define(Class) {
  const tag = Class.tag;
  if (!tag) throw new Error("UI.define: Class.tag is required");
  installProps(Class);
  if (!customElements.get(tag)) customElements.define(tag, Class);
  else if (__DEV__) console.warn(`[UI-W001] <${tag}> is already defined`);
  components.set(tag, Class);
}

export const getComponents = () => components;
export const whenDefined = tag => customElements.whenDefined(tag);
