// Declarative props: `static props = { name: { type, attribute, default } }`.
// Types: string | boolean | number | array | object | any. Attribute reflection is automatic when `attribute` is set.

export function allProps(Class) {
  const chain = [];
  for (let c = Class; c && c !== HTMLElement; c = Object.getPrototypeOf(c)) {
    if (Object.prototype.hasOwnProperty.call(c, "props")) chain.unshift(c.props);
  }
  return Object.assign({}, ...chain);
}

export function coerce(value, type) {
  switch (type) {
    case "boolean": return value !== null && value !== undefined && value !== false && value !== "false";
    case "number": return value === "" || value == null ? null : Number(value);
    case "string": return value == null ? "" : String(value);
    case "array": return Array.isArray(value) ? value : typeof value === "string" ? safeJson(value, []) : [];
    case "object": return value && typeof value === "object" ? value : typeof value === "string" ? safeJson(value, {}) : {};
    default: return value;
  }
}

function safeJson(s, fallback) {
  try { return JSON.parse(s); } catch { return fallback; }
}

function reflect(el, attr, value, type) {
  if (type === "array" || type === "object") return;
  if (type === "boolean") {
    if (value) { if (!el.hasAttribute(attr)) el.setAttribute(attr, ""); }
    else el.removeAttribute(attr);
    return;
  }
  if (value == null || value === false || value === "") {
    if (el.hasAttribute(attr)) el.removeAttribute(attr);
  } else if (el.getAttribute(attr) !== String(value)) {
    el.setAttribute(attr, String(value));
  }
}

/** Define accessors for the schema on the prototype of `Class` (idempotent). */
export function installProps(Class) {
  if (Object.prototype.hasOwnProperty.call(Class, "__propsInstalled")) return;
  Object.defineProperty(Class, "__propsInstalled", { value: true });
  const schema = allProps(Class);
  const proto = Class.prototype;
  for (const [name, desc] of Object.entries(schema)) {
    if (Object.getOwnPropertyDescriptor(proto, name)?.get) continue;
    Object.defineProperty(proto, name, {
      configurable: true,
      enumerable: true,
      get() {
        const v = this.__props?.[name];
        return v === undefined ? (Array.isArray(desc.default) ? desc.default.slice() : desc.default) : v;
      },
      set(value) {
        const store = this.__props || (this.__props = {});
        const old = this[name];
        const next = coerce(value, desc.type);
        if (old === next && store[name] !== undefined) return;
        store[name] = next;
        if (desc.attribute && this.__reflecting !== desc.attribute) {
          this.__reflecting = desc.attribute;
          try { reflect(this, desc.attribute, next, desc.type); } finally { this.__reflecting = null; }
        }
        this.propsChanged?.(name, old, next);
        this.requestRender?.();
      }
    });
  }
}

export function observedAttributesOf(Class) {
  return Object.values(allProps(Class)).map(d => d.attribute).filter(Boolean);
}
