// Entry point: assembles window.UI and defines all <ui-*> elements.

import { html, render } from "./template/html.js";
import * as directives from "./template/directives.js";
import { UIElement } from "./base/UIElement.js";
import { UIFormElement } from "./base/UIFormElement.js";
import { UIListElement } from "./base/UIListElement.js";
import { UIOverlayElement } from "./base/UIOverlayElement.js";
import { define, getComponents, whenDefined } from "./services/registry.js";
import { buildCreateNamespace } from "./services/create.js";
import { theme } from "./services/theme.js";
import { keys } from "./services/keys.js";
import { commands } from "./services/commands.js";
import { i18n } from "./services/i18n.js";
import { form } from "./services/form.js";
import { dialog } from "./services/dialog.js";
import { toast } from "./components/toast/ui-toast-region.js";
import { allComponents } from "./components/index.js";

theme.init();

for (const Component of allComponents) define(Component);

const UI = {
  version: "2.0.0-alpha.3",
  components: getComponents(),
  define,
  whenDefined,
  html,
  render,
  ...directives,
  Element: UIElement,
  FormElement: UIFormElement,
  ListElement: UIListElement,
  OverlayElement: UIOverlayElement,
  theme,
  keys,
  commands,
  i18n,
  form,
  dialog,
  toast,
  alert: (...a) => dialog.alert(...a),
  confirm: (...a) => dialog.confirm(...a),
  prompt: (...a) => dialog.prompt(...a)
};

buildCreateNamespace(UI, UI.components);

if (typeof window !== "undefined") window.UI = UI;

export { UI };
export default UI;
