import { UIElement } from "./UIElement.js";

/** Base for form controls. Participates in native forms through a real inner control (light DOM). */
export class UIFormElement extends UIElement {
  static props = {
    name: { type: "string", attribute: "name", default: "" },
    value: { type: "string", attribute: "value", default: "" },
    label: { type: "string", attribute: "label", default: "" },
    required: { type: "boolean", attribute: "required", default: false },
    readonly: { type: "boolean", attribute: "readonly", default: false },
    primary: { type: "boolean", attribute: "primary", default: false }
  };

  init() {
    this.__defaultValue = this.value;
    const form = this.closest("form");
    if (form) {
      const onReset = () => queueMicrotask(() => this.reset());
      form.addEventListener("reset", onReset);
      this.registerCleanup(() => form.removeEventListener("reset", onReset));
    }
  }

  get form() { return this.closest("form"); }
  get control() { return this.querySelector("input, select, textarea, button"); }
  get validity() { return this.control?.validity ?? { valid: true }; }
  get validationMessage() { return this.control?.validationMessage ?? ""; }
  checkValidity() { return this.control?.checkValidity?.() ?? true; }
  reportValidity() { return this.control?.reportValidity?.() ?? true; }
  setCustomValidity(message) { this.control?.setCustomValidity?.(message); }
  focus(options) { this.control?.focus(options); }
  select() { this.control?.select?.(); }

  reset() {
    this.value = this.__defaultValue ?? "";
    this.requestRender();
  }
}
